nodes=['198948', '194947', '218370', '202949', '282455', '248143']
import math, cmath; v=[float(x) for x in nodes]; F=[sum(v[n]*cmath.exp(-2j*math.pi*k*n/6) for n in range(6)) for k in range(6)]; tr_spec=sum(1.0/f for f in F).real; A=[[v[(j-i)%6] for j in range(6)]+[1.0 if i==j else 0.0 for j in range(6)] for i in range(6)]; exec("for i in range(6):\n p=A[i][i]; A[i]=[x/p for x in A[i]]\n for k in range(6):\n  if k!=i: f=A[k][i]; A[k]=[A[k][j]-f*A[i][j] for j in range(12)]"); tr_gauss=sum(A[i][i+6] for i in range(6)); print(f"1.EXACT_TRACE_UNIFICATION: Spectral={tr_spec:.12e} vs Gauss={tr_gauss:.12e} | Match={100.0-abs(tr_spec-tr_gauss)/abs(tr_gauss)*100:.12f}%")
